package de.wattpit.app;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import de.wattpit.app.core.MigrationCipher;
import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Production snapshots, encryption and fresh/existing guards. Real SQLite; Android UID/SAF have separate instrumentation proofs. */
public final class BackupProof {
    static void check(boolean ok,String s){if(!ok)throw new AssertionError(s);System.out.println("PASS "+s);}
    static long scalar(SQLiteDatabase db,String q){try(Cursor c=db.rawQuery(q,null)){return c.moveToFirst()?c.getLong(0):0;}}
    public static void main(String[] args)throws Exception{
        Class.forName("org.sqlite.JDBC");Path root=Path.of(args[0]);Files.createDirectories(root);LanSyncProof.TestContext c=new LanSyncProof.TestContext(root.resolve("preset"));JSONObject preset=new JSONObject(Files.readString(Path.of("app/src/main/assets/ui-preset.json")));SharedPreferences fresh=c.getSharedPreferences("new",0);UiPreset.install(fresh,preset);check(fresh.getInt("display-scale-v1",0)==75&&new JSONObject(fresh.getString("dashboard-v1","{}")).getJSONArray("tiles").length()==21,"approved fresh presentation has 75 percent size and 21 overview tiles");
        JSONObject workspace=AutarPieConfig.workspace(preset.getJSONObject("workspace").toString());AutarPieConfig.appearance(preset.getJSONObject("appearance").toString());ConfigurationBackup.dashboard(preset.getJSONObject("dashboard"));check(workspace.getJSONArray("pages").length()==8&&workspace.getJSONArray("navigation").getString(0).equals("history"),"all eight dashboards and approved navigation survive validation");Map<String,?> prior=fresh.getAll();UiPreset.install(fresh,new JSONObject());check(prior.equals(fresh.getAll()),"second start makes no presentation change");SharedPreferences existing=c.getSharedPreferences("existing",0);existing.edit().putString("dashboard-v1","own-layout").putInt("display-scale-v1",110).putString("connection","preserved").commit();UiPreset.install(existing,preset);check(existing.getString("dashboard-v1","").equals("own-layout")&&existing.getInt("display-scale-v1",0)==110&&existing.getString("connection","").equals("preserved")&&!existing.getBoolean(UiPreset.MARKER,true),"existing layouts, size and connections remain untouched");check(!preset.has("weatherPlace")&&!preset.has("equipment")&&!preset.toString().matches("(?is).*(?:[0-9a-f]{2}:){5}[0-9a-f]{2}.*"),"public defaults have no site, equipment or Bluetooth addresses");
        File live=root.resolve("live.db").toFile();try(SQLiteDatabase db=SQLiteDatabase.openDatabase(live.toString(),null,0)){
            db.execSQL("PRAGMA journal_mode=WAL");db.execSQL("CREATE TABLE events(value TEXT,optional REAL,raw BLOB)");db.execSQL("INSERT INTO events(rowid,value,optional,raw) VALUES(7,'first',NULL,X'0011FF'),(10009,'second',2.5,X'2233')");db.execSQL("CREATE TABLE meta(n INTEGER)");db.execSQL("INSERT INTO meta VALUES(2)");db.execSQL("CREATE TRIGGER count_events AFTER INSERT ON events BEGIN UPDATE meta SET n=n+1; END");db.execSQL("CREATE INDEX by_value ON events(value)");db.execSQL("CREATE VIEW visible AS SELECT value FROM events");db.execSQL("CREATE TABLE sequence_test(id INTEGER PRIMARY KEY AUTOINCREMENT,value TEXT)");db.execSQL("INSERT INTO sequence_test(id,value) VALUES(999,'removed')");db.execSQL("DELETE FROM sequence_test");db.execSQL("PRAGMA user_version=37");
            File dest=root.resolve("snapshot.db").toFile();BackupSnapshot.copy(live,dest);try(SQLiteDatabase copy=SQLiteDatabase.openDatabase(dest.toString(),null,0)){
                check(scalar(copy,"SELECT MAX(rowid) FROM events")==10009,"sparse source rowids survive the snapshot");check(scalar(copy,"SELECT COUNT(*) FROM events WHERE optional IS NULL")==1,"unknown values remain NULL");check(scalar(copy,"SELECT COUNT(*) FROM events WHERE hex(raw)='0011FF'")==1,"binary values survive exactly");check(scalar(copy,"SELECT n FROM meta")==2,"copying rows never runs capture triggers");check(scalar(copy,"PRAGMA user_version")==37,"schema version is retained");copy.execSQL("INSERT INTO events(value) VALUES('third')");check(scalar(copy,"SELECT n FROM meta")==3&&scalar(copy,"SELECT COUNT(*) FROM visible")==3,"restored capture trigger, index and view work");copy.execSQL("INSERT INTO sequence_test(value) VALUES('new')");check(scalar(copy,"SELECT id FROM sequence_test")==1000,"deleted AUTOINCREMENT high-water mark remains preserved");
            }
            db.execSQL("CREATE TABLE pairs(id INTEGER,side INTEGER,PRIMARY KEY(id,side))");db.beginTransaction();try{for(int i=0;i<8000;i++){db.execSQL("INSERT INTO pairs VALUES(?,0)",new Object[]{i});db.execSQL("INSERT INTO pairs VALUES(?,1)",new Object[]{i});}db.setTransactionSuccessful();}finally{db.endTransaction();}
            ExecutorService executor=Executors.newSingleThreadExecutor();java.util.concurrent.atomic.AtomicBoolean stop=new java.util.concurrent.atomic.AtomicBoolean();Future<?> writer=executor.submit(()->{try(SQLiteDatabase w=SQLiteDatabase.openDatabase(live.toString(),null,0)){int i=8000;while(!stop.get()){w.beginTransaction();try{w.execSQL("INSERT INTO pairs VALUES(?,0)",new Object[]{i});w.execSQL("INSERT INTO pairs VALUES(?,1)",new Object[]{i++});w.setTransactionSuccessful();}finally{w.endTransaction();}}}});
            try{for(int i=0;i<3;i++){File file=root.resolve("concurrent-"+i+".db").toFile();BackupSnapshot.copy(live,file);try(SQLiteDatabase copy=SQLiteDatabase.openDatabase(file.toString(),null,0)){check(scalar(copy,"SELECT COUNT(*) FROM (SELECT id FROM pairs GROUP BY id HAVING COUNT(*)<>2)")==0,"concurrent source transactions remain atomic in snapshot "+i);}}}finally{stop.set(true);writer.get(10,TimeUnit.SECONDS);executor.shutdownNow();}
            check(scalar(db,"SELECT COUNT(*) FROM events")==2,"snapshot creation preserves the live source");
        }
        byte[] original=Files.readAllBytes(root.resolve("snapshot.db"));char[] key="Neutral-backup-test-2026!".toCharArray();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(OutputStream out=MigrationCipher.encrypt(bytes,key)){out.write(original);}byte[] encrypted=bytes.toByteArray();try(InputStream in=MigrationCipher.decrypt(new ByteArrayInputStream(encrypted),key)){check(Arrays.equals(original,in.readAllBytes()),"encrypted snapshot round-trips byte for byte");}boolean denied=false;try(InputStream in=MigrationCipher.decrypt(new ByteArrayInputStream(encrypted),"incorrect-password-123".toCharArray())){in.readAllBytes();}catch(IOException e){denied=true;}check(denied,"wrong backup password is rejected");encrypted[encrypted.length-1]^=1;denied=false;try(InputStream in=MigrationCipher.decrypt(new ByteArrayInputStream(encrypted),key)){in.readAllBytes();}catch(IOException e){denied=true;}check(denied,"damaged final authentication is rejected");Arrays.fill(key,'\0');
        long now=Instant.parse("2026-11-17T00:00:00Z").toEpochMilli();check(BackupScheduler.next(now,"03:17","Europe/Berlin")==Instant.parse("2026-11-17T02:17:00Z").toEpochMilli(),"daily backup respects the chosen local minute");for(String at:new String[]{"2026-03-28T23:59:00Z","2026-10-25T02:00:00Z"}){long start=Instant.parse(at).toEpochMilli();check(BackupScheduler.next(start,"02:30","Europe/Berlin")>start,"DST yields a future backup: "+at);}
    }
}
